// Build-time patch for the compiled OpenAPI importer (openapi.parser.js).
//
// Upstream flattenSchema() maps every request-body property to
// `{ type: prop.type || 'string' }`. Specs generated by FastAPI/pydantic
// (e.g. Nansen, OpenAPI 3.1) wrap optional fields as
// `anyOf: [{ $ref: ... }]` / `anyOf: [{ type: 'array', ... }, { type: 'null' }]`
// with no top-level `type`, so objects, arrays, booleans and numbers were all
// imported as `string`. MCP clients then serialize e.g. `filters` to a JSON
// string and the upstream API rejects it ("Invalid value for body -> filters").
//
// This resolves the effective type through $ref / anyOf / oneOf / allOf,
// ignoring `null` branches. Genuinely mixed unions get no `type` (accepted
// as-is by the MCP layer) instead of a wrong one. Properties with no type
// information at all keep upstream's 'string' default.
'use strict';
const fs = require('fs');
const target = process.argv[2];
let src = fs.readFileSync(target, 'utf8');

const anchor = "const entry = { type: prop.type || 'string' };";
const count = src.split(anchor).length - 1;
if (count !== 1) { console.error(`FATAL: expected anchor exactly once, found ${count}`); process.exit(1); }

const helper = `
function __amcpInferType(s, api, d) {
    if (!s || typeof s !== 'object' || d > 10) return undefined;
    if (typeof s.$ref === 'string') {
        if (!s.$ref.startsWith('#/')) return undefined;
        let r = api;
        for (const seg of s.$ref.slice(2).split('/')) r = r?.[seg.replace(/~1/g, '/').replace(/~0/g, '~')];
        return __amcpInferType(r, api, d + 1);
    }
    if (typeof s.type === 'string') return s.type === 'null' ? undefined : s.type;
    if (Array.isArray(s.type)) {
        const ts = s.type.filter((t) => t !== 'null');
        return ts.length === 1 ? ts[0] : ts.length ? null : undefined;
    }
    if (s.properties || s.allOf) return 'object';
    if (s.items) return 'array';
    if (Array.isArray(s.enum) && s.enum.length) {
        const k = typeof s.enum[0];
        return k === 'number' ? 'number' : k === 'boolean' ? 'boolean' : 'string';
    }
    const branches = s.anyOf || s.oneOf;
    if (Array.isArray(branches)) {
        const ts = [...new Set(branches.map((b) => __amcpInferType(b, api, d + 1)).filter((t) => t !== undefined))];
        if (ts.length === 1) return ts[0];
        return ts.length ? null : undefined;
    }
    return undefined;
}
`;
const replacement =
  "const __amcpType = prop.type || __amcpInferType(prop, api, 0); " +
  "const entry = __amcpType === null ? {} : { type: __amcpType || 'string' };";

src = src.replace(anchor, replacement);
// Insert the helper right after the "use strict" prologue.
if (!src.startsWith('"use strict";')) { console.error('FATAL: unexpected file prologue'); process.exit(1); }
src = src.replace('"use strict";', '"use strict";' + helper);

if (src.includes(anchor)) { console.error('FATAL: unpatched anchor remains'); process.exit(1); }
if ((src.split('__amcpInferType(prop, api, 0)').length - 1) !== 1) { console.error('FATAL: patch not applied exactly once'); process.exit(1); }
fs.writeFileSync(target, src);
console.log('OPENAPI ANYOF PATCH OK:', target);
